// ============================================================
// คัดกรองและจัดข้อมูลก่อนลง Google Sheets
// ============================================================
// เก็บข้อมูลครบทุกช่องเหมือนเดิม เพราะการตัดคอลัมน์ทิ้งไม่ได้ช่วยประหยัดเครดิต
// Apify คิดเงินตอนไปดึงร้าน ไม่ได้คิดตามจำนวนช่องที่ส่งกลับมา
// ดึงมาแล้วก็เก็บไว้ให้หมด เผื่อวันหลังได้ใช้ — ดึงใหม่ต้องจ่ายใหม่
//
// สิ่งที่ทำตรงนี้
//   - ตัดร้านที่ไม่มีชื่อ (ข้อมูลเสีย)
//   - ตัดร้านซ้ำ (Apify คืนซ้ำได้เมื่อค้นหลายคำ)
//   - จัดเบอร์โทรเป็น 08x-xxx-xxxx กัน Google Sheets ตัดเลข 0 นำหน้าทิ้ง
//   - เรียงร้านที่ติดต่อได้ขึ้นก่อน
// ============================================================

// ── สวิตช์ตัวเดียว ────────────────────────────────────────────
// true  = เก็บเฉพาะมือถือ (06x / 08x / 09x) ตัดเบอร์บ้านกับร้านที่ไม่มีเบอร์ทิ้ง
// false = เก็บทุกร้าน ไม่ว่าจะมีเบอร์หรือไม่ (เหมือนตอนแรก)
const เอาเฉพาะมือถือ = false;
// ──────────────────────────────────────────────────────────────

const form = $('ฟอร์มกรอกคำค้นหา').first().json;
const searchTerm = form['คำค้นหา'] || '';
const searchArea = form['พื้นที่'] || '';
const today = new Date().toISOString().slice(0, 10);

// คืน { เบอร์, เป็นมือถือไหม }
function cleanPhone(raw) {
  if (!raw) return { phone: '', mobile: false };
  let p = String(raw).replace(/[^0-9+]/g, '');
  if (p.startsWith('+66')) p = '0' + p.slice(3);        // +66812345678 -> 0812345678
  else if (p.startsWith('66') && p.length > 10) p = '0' + p.slice(2);

  const mobile = /^0[689]\d{8}$/.test(p);

  // ใส่ขีดคั่น ทำให้ชีตมองเป็นข้อความ เลข 0 นำหน้าไม่หาย
  if (/^0\d{9}$/.test(p)) return { phone: p.slice(0,3) + '-' + p.slice(3,6) + '-' + p.slice(6), mobile };
  if (/^0\d{8}$/.test(p)) return { phone: p.slice(0,2) + '-' + p.slice(2,5) + '-' + p.slice(5), mobile };
  return { phone: p, mobile };
}

// Apify เก็บอีเมลไว้หลายที่ แล้วแต่ว่าเปิด contacts enrichment ไว้หรือเปล่า
function findEmail(d) {
  if (Array.isArray(d.emails) && d.emails.length) return d.emails[0];
  if (d.email) return d.email;
  const c = d.contactDetails || {};
  if (Array.isArray(c.emails) && c.emails.length) return c.emails[0];
  return '';
}

const seen = new Set();
const rows = [];
let noName = 0, dup = 0, skipped = 0;

for (const item of $input.all()) {
  const d = item.json;

  if (!d.title) { noName++; continue; }

  const key = d.placeId || `${d.title}|${d.address || ''}`;
  if (seen.has(key)) { dup++; continue; }
  seen.add(key);

  const { phone, mobile } = cleanPhone(d.phoneUnformatted || d.phone);
  if (เอาเฉพาะมือถือ && !mobile) { skipped++; continue; }

  rows.push({
    json: {
      'ชื่อร้าน': d.title || '',
      'ประเภท': d.categoryName || '',
      'ที่อยู่': d.address || d.street || '',
      'เบอร์โทร': phone,
      'อีเมล': findEmail(d),
      'เว็บไซต์': d.website || '',
      'คะแนน': d.totalScore ?? d.score ?? '',
      'จำนวนรีวิว': d.reviewsCount ?? '',
      'เวลาทำการ': Array.isArray(d.openingHours)
        ? d.openingHours.map(h => `${h.day} ${h.hours}`).join(' / ')
        : '',
      'ลิงก์ Maps': d.url || d.searchPageUrl || '',
      'มีเบอร์โทร': phone ? (mobile ? 'มือถือ' : 'เบอร์บ้าน') : 'ไม่มี',
      'คำค้นหา': searchTerm,
      'พื้นที่': searchArea,
      'วันที่ดึง': today,
    },
  });
}

// ร้านที่ติดต่อได้ขึ้นก่อน มือถือ > เบอร์บ้าน > ไม่มีเบอร์
const rank = { 'มือถือ': 0, 'เบอร์บ้าน': 1, 'ไม่มี': 2 };
rows.sort((a, b) => rank[a.json['มีเบอร์โทร']] - rank[b.json['มีเบอร์โทร']]);

const มือถือ = rows.filter(r => r.json['มีเบอร์โทร'] === 'มือถือ').length;
const บ้าน = rows.filter(r => r.json['มีเบอร์โทร'] === 'เบอร์บ้าน').length;
console.log(`เข้ามา ${$input.all().length} | เก็บ ${rows.length} | ` +
            `มือถือ ${มือถือ} | เบอร์บ้าน ${บ้าน} | ไม่มีเบอร์ ${rows.length - มือถือ - บ้าน} | ` +
            `ไม่มีชื่อ ${noName} | ซ้ำ ${dup} | ถูกกรองออก ${skipped}`);

if (rows.length === 0) {
  throw new Error('ไม่พบข้อมูลร้านเลย — ลองใช้คำค้นหาที่กว้างขึ้น หรือเปลี่ยนพื้นที่');
}

return rows;
